#!/usr/bin/env python3
"""Regenerates client/src/TPConfig.h with a fresh deployment-specific HWID salt.

Usage: python gen_hwid_config.py
Outputs also print the build fingerprint so you can track which build introduced it.
"""
import secrets
from pathlib import Path

HEADER = """#pragma once
// Deployment-specific HWID composition. Generated by client/tools/gen_hwid_config.py.
// Never ship a build whose SALT is empty. Changing SALT invalidates every license
// bound on the previous format; clear those bindings (Unbind) after rotating.
#define TP_HWID_SALT "{salt}"
#define TP_HWID_FORMAT {fmt}
#define TP_HWID_COMPONENTS "guid|volume|cpu"
"""

target = Path(__file__).resolve().parent.parent / "src" / "TPConfig.h"
salt = secrets.token_hex(32)
target.write_text(HEADER.format(salt=salt, fmt=1), encoding="utf-8")
print("Wrote:", target)
print("New HWID SALT:", salt)
print("NOTE: re-issue / unbind existing licenses after deploying this build.")
